def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    ones=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    n=len(ones)
    for i in range(n):
        for j in range(i+1,n):
            a,b=ones[i],ones[j]
            dr,dc=b[0]-a[0],b[1]-a[1]
            if abs(dr)!=abs(dc) or dr==0: continue
            s=1 if dr>0 else -1
            t=1 if dc>0 else -1
            seg=[(a[0]+s*k,a[1]+t*k) for k in range(1,abs(dr))]
            for (r,c) in seg:
                if g[r][c]==0: out[r][c]=1
            for (pr,pc) in seg:
                if g[pr][pc]==6:
                    pd=(1,-1) if dr*dc>0 else (1,1)
                    for s2 in (1,-1):
                        r,c=pr+pd[0]*s2,pc+pd[1]*s2
                        while 0<=r<h and 0<=c<w:
                            out[r][c]=6
                            r+=pd[0]*s2; c+=pd[1]*s2
    return out

